"use client";

import { cn } from "@/lib/utils";
import { Slot as SlotPrimitive } from "radix-ui";
import { useLayoutEffect } from "radix-ui/internal";
import * as React from "react";

import {
  addQueryNode,
  createQueryGroup,
  createQueryRule,
  getIsQueryGroup,
  getIsQueryRuleMultiple,
  getQueryOperatorLabel,
  getQueryOperators,
  type QueryCombinator,
  type QueryField,
  type QueryFieldOption,
  type QueryGroup,
  type QueryNode,
  type QueryOperator,
  type QueryRule,
  type QueryValue,
  removeQueryNode,
  setQueryRuleField,
  setQueryRuleOperator,
  setQueryRuleValues,
  updateQueryNode,
} from "./query-builder-lib";
import { Button } from "@/components/ui/button";
import {
  Faceted,
  FacetedBadge,
  FacetedClear,
  FacetedContent,
  FacetedEmpty,
  FacetedGroup,
  FacetedInput,
  FacetedItem,
  FacetedItemIndicator,
  FacetedList,
  FacetedTrigger,
  FacetedValue,
} from "./query-builder-faceted";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

import { ChevronDownIcon, ListPlusIcon, PlusIcon, Trash2Icon } from "lucide-react";
const ROOT_NAME = "QueryBuilder";
const GROUP_NAME = "QueryBuilderGroup";
const GROUP_HEADER_NAME = "QueryBuilderGroupHeader";
const GROUP_TITLE_NAME = "QueryBuilderGroupTitle";
const GROUP_FOOTER_NAME = "QueryBuilderGroupFooter";
const GROUP_CONTENT_NAME = "QueryBuilderGroupContent";
const RULE_LIST_NAME = "QueryBuilderRuleList";
const RULE_NAME = "QueryBuilderRule";
const COMBINATOR_NAME = "QueryBuilderCombinator";
const CONNECTOR_NAME = "QueryBuilderConnector";
const NEGATE_NAME = "QueryBuilderNegate";
const FIELD_NAME = "QueryBuilderField";
const OPERATOR_NAME = "QueryBuilderOperator";
const VALUE_NAME = "QueryBuilderValue";
const ADD_RULE_NAME = "QueryBuilderAddRule";
const ADD_GROUP_NAME = "QueryBuilderAddGroup";
const REMOVE_NAME = "QueryBuilderRemove";

interface DivProps extends React.ComponentProps<"div"> {
  asChild?: boolean;
}

const DEFAULT_LABELS = {
  where: "Where",
  and: "And",
  or: "Or",
  all: "All",
  any: "Any",
  not: "Not",
  combinator: "Combinator",
  matchAll: "All of the following are true…",
  matchAny: "Any of the following are true…",
  matchNotAll: "Not all of the following are true…",
  matchNone: "None of the following are true…",
  field: "Field",
  searchFields: "Search fields",
  noFields: "No fields found.",
  operator: "Operator",
  operatorLabel: getQueryOperatorLabel,
  searchOperators: "Search operators",
  noOperators: "No operators found.",
  enterValue: "Enter a value",
  selectValue: "Select a value",
  selectValues: "Select values",
  searchValues: (field: string) => `Search ${field.toLowerCase()}`,
  selected: (count: number) => `${count} selected`,
  noValue: "no value",
  noValues: "No results.",
  between: "and",
  from: "from",
  to: "to",
  true: "True",
  false: "False",
  addRule: "Add rule",
  addGroup: "Add group",
  removeRule: "Remove rule",
  removeGroup: "Remove group",
};

type QueryBuilderLabels = typeof DEFAULT_LABELS;

interface QueryBuilderContextValue {
  fields: QueryField[];
  labels: QueryBuilderLabels;
  value: QueryGroup;
  setValue: (updater: (value: QueryGroup) => QueryGroup) => void;
  maxDepth: number;
  disabled: boolean;
}

const QueryBuilderContext =
  React.createContext<QueryBuilderContextValue | null>(null);

function useQueryBuilderContext(consumerName: string) {
  const context = React.useContext(QueryBuilderContext);
  if (!context) {
    throw new Error(`\`${consumerName}\` must be used within \`${ROOT_NAME}\``);
  }
  return context;
}

interface GroupContextValue {
  group: QueryGroup;
  depth: number;
  isRoot: boolean;
}

const GroupContext = React.createContext<GroupContextValue | null>(null);

function useGroupContext(consumerName: string) {
  const context = React.useContext(GroupContext);
  if (!context) {
    throw new Error(
      `\`${consumerName}\` must be used within \`${GROUP_NAME}\``,
    );
  }
  return context;
}

const NestedGroupContext = React.createContext<QueryGroup | null>(null);

const GroupTemplateContext = React.createContext<QueryBuilderGroupProps | null>(
  null,
);

interface NodeContextValue {
  index: number;
  group: QueryGroup;
}

const NodeContext = React.createContext<NodeContextValue | null>(null);

const RuleContext = React.createContext<QueryRule | null>(null);

function useRuleContext(consumerName: string) {
  const context = React.useContext(RuleContext);
  if (!context) {
    throw new Error(`\`${consumerName}\` must be used within \`${RULE_NAME}\``);
  }
  return context;
}

function useQueryActions(consumerName: string) {
  const { setValue } = useQueryBuilderContext(consumerName);
  return React.useMemo(
    () => ({
      update: (id: string, updater: (node: QueryNode) => QueryNode) =>
        setValue((value) => updateQueryNode(value, id, updater)),
      add: (groupId: string, node: QueryNode) =>
        setValue((value) => addQueryNode(value, groupId, node)),
      remove: (id: string) => setValue((value) => removeQueryNode(value, id)),
    }),
    [setValue],
  );
}

interface QueryBuilderProps extends Omit<DivProps, "defaultValue"> {
  fields: QueryField[];
  value?: QueryGroup;
  defaultValue?: QueryGroup;
  onValueChange?: (value: QueryGroup) => void;
  maxDepth?: number;
  labels?: Partial<QueryBuilderLabels>;
  disabled?: boolean;
}

function QueryBuilder({
  fields,
  value: valueProp,
  defaultValue,
  onValueChange: onValueChangeProp,
  maxDepth = 2,
  labels: labelsProp,
  disabled = false,
  asChild,
  className,
  ...props
}: QueryBuilderProps) {
  const [uncontrolledValue, setUncontrolledValue] = React.useState(
    () => defaultValue ?? createQueryGroup(),
  );
  const isControlled = valueProp !== undefined;
  const value = valueProp ?? uncontrolledValue;

  const valueRef = React.useRef(value);
  useLayoutEffect(() => {
    valueRef.current = value;
  });

  const setValue = React.useCallback(
    (updater: (value: QueryGroup) => QueryGroup) => {
      const next = updater(valueRef.current);
      if (next === valueRef.current) return;
      valueRef.current = next;
      if (!isControlled) setUncontrolledValue(next);
      onValueChangeProp?.(next);
    },
    [isControlled, onValueChangeProp],
  );

  const labels = React.useMemo<QueryBuilderLabels>(
    () => ({
      ...DEFAULT_LABELS,
      ...Object.fromEntries(
        Object.entries(labelsProp ?? {}).filter(
          ([, label]) => label !== undefined,
        ),
      ),
    }),
    [labelsProp],
  );

  const contextValue = React.useMemo<QueryBuilderContextValue>(
    () => ({ fields, labels, value, setValue, maxDepth, disabled }),
    [fields, labels, value, setValue, maxDepth, disabled],
  );

  const RootPrimitive = asChild ? SlotPrimitive.Slot : "div";

  return (
    <QueryBuilderContext.Provider value={contextValue}>
      <RootPrimitive
        role="group"
        data-slot="query-builder"
        data-disabled={disabled ? "" : undefined}
        {...props}
        className={cn(
          "min-w-64 gap-2 @container/query-builder flex flex-col",
          className,
        )}
      />
    </QueryBuilderContext.Provider>
  );
}

interface QueryBuilderGroupProps extends Omit<DivProps, "children"> {
  children?: React.ReactNode | ((group: QueryGroup) => React.ReactNode);
}

function QueryBuilderGroup(groupProps: QueryBuilderGroupProps) {
  const { value } = useQueryBuilderContext(GROUP_NAME);
  const parent = React.useContext(GroupContext);
  const nestedGroup = React.useContext(NestedGroupContext);
  const template = React.useContext(GroupTemplateContext);

  const { asChild, className, ref, id, children, ...props } =
    parent && template
      ? {
          ...template,
          ...groupProps,
          className: cn(template.className, groupProps.className),
        }
      : groupProps;

  const group = nestedGroup ?? value;
  const depth = parent ? parent.depth + 1 : 0;

  const groupContext = React.useMemo<GroupContextValue>(
    () => ({ group, depth, isRoot: !parent }),
    [group, depth, parent],
  );

  const GroupPrimitive = asChild ? SlotPrimitive.Slot : "div";

  const element = (
    <GroupContext.Provider value={groupContext}>
      <NestedGroupContext.Provider value={null}>
        <GroupPrimitive
          ref={ref}
          id={id}
          role={parent ? "listitem" : "group"}
          data-slot="query-builder-group"
          data-depth={depth}
          data-combinator={group.combinator}
          data-not={group.not ? "" : undefined}
          {...props}
          className={cn("items-start gap-1.5 @max-[28rem]/query-builder:gap-1.5 @max-[28rem]/query-builder:flex-col @max-[28rem]/query-builder:items-stretch flex", className)}
        >
          {typeof children === "function" ? children(group) : children}
        </GroupPrimitive>
      </NestedGroupContext.Provider>
    </GroupContext.Provider>
  );

  if (parent) return element;

  return (
    <GroupTemplateContext.Provider
      value={{ asChild, className, children, ...props }}
    >
      {element}
    </GroupTemplateContext.Provider>
  );
}

function QueryBuilderGroupHeader({ asChild, className, ...props }: DivProps) {
  const { depth } = useGroupContext(GROUP_HEADER_NAME);
  const HeaderPrimitive = asChild ? SlotPrimitive.Slot : "div";

  return (
    <HeaderPrimitive
      data-slot="query-builder-group-header"
      data-depth={depth}
      {...props}
      className={cn(
        "gap-0.5 ps-1.5 text-sm text-muted-foreground flex items-center",
        className,
      )}
    />
  );
}

function QueryBuilderGroupTitle({
  asChild,
  className,
  children,
  ...props
}: DivProps) {
  const { labels } = useQueryBuilderContext(GROUP_TITLE_NAME);
  const { group } = useGroupContext(GROUP_TITLE_NAME);
  const title =
    group.combinator === "and"
      ? group.not
        ? labels.matchNotAll
        : labels.matchAll
      : group.not
        ? labels.matchNone
        : labels.matchAny;

  const TitlePrimitive = asChild ? SlotPrimitive.Slot : "div";

  return (
    <TitlePrimitive
      data-slot="query-builder-group-title"
      dir="auto"
      {...props}
      className={cn("flex-1 truncate", className)}
    >
      {asChild ? (
        <SlotPrimitive.Slottable child={children}>
          {(content) => content ?? title}
        </SlotPrimitive.Slottable>
      ) : (
        (children ?? title)
      )}
    </TitlePrimitive>
  );
}

function QueryBuilderGroupFooter({ asChild, className, ...props }: DivProps) {
  const { depth } = useGroupContext(GROUP_FOOTER_NAME);
  const FooterPrimitive = asChild ? SlotPrimitive.Slot : "div";

  return (
    <FooterPrimitive
      data-slot="query-builder-group-footer"
      data-depth={depth}
      {...props}
      className={cn(
        "gap-1 flex items-center",
        className,
      )}
    />
  );
}

function QueryBuilderGroupContent({ asChild, className, ...props }: DivProps) {
  const { depth } = useGroupContext(GROUP_CONTENT_NAME);
  const ContentPrimitive = asChild ? SlotPrimitive.Slot : "div";

  return (
    <ContentPrimitive
      data-slot="query-builder-group-content"
      data-depth={depth}
      {...props}
      className={cn(
        "min-w-0 flex-1 gap-1.5 not-data-[depth=0]:rounded-lg not-data-[depth=0]:border not-data-[depth=0]:bg-muted/20 not-data-[depth=0]:p-2 @container/query-builder flex flex-col",
        className,
      )}
    />
  );
}

interface QueryBuilderRuleListProps extends Omit<
  React.ComponentProps<"div">,
  "children"
> {
  children?: React.ReactNode | ((node: QueryNode) => React.ReactNode);
}

function QueryBuilderRuleList({
  className,
  children,
  ...props
}: QueryBuilderRuleListProps) {
  const { group } = useGroupContext(RULE_LIST_NAME);

  return (
    <div
      role="list"
      data-slot="query-builder-rule-list"
      {...props}
      className={cn("gap-1.5 flex flex-col", className)}
    >
      {group.rules.map((node, index) => (
        <NodeContext.Provider key={node.id} value={{ index, group }}>
          {getIsQueryGroup(node) ? (
            <NestedGroupContext.Provider value={node}>
              {typeof children === "function" ? (
                children(node)
              ) : (
                <QueryBuilderGroup />
              )}
            </NestedGroupContext.Provider>
          ) : (
            <RuleContext.Provider value={node}>
              {typeof children === "function" ? children(node) : children}
            </RuleContext.Provider>
          )}
        </NodeContext.Provider>
      ))}
    </div>
  );
}

function QueryBuilderRule({ asChild, className, ...props }: DivProps) {
  const rule = useRuleContext(RULE_NAME);

  const RulePrimitive = asChild ? SlotPrimitive.Slot : "div";

  return (
    <RulePrimitive
      role="listitem"
      data-slot="query-builder-rule"
      data-operator={rule.operator}
      {...props}
      className={cn("gap-1.5 *:data-[slot=button-group]:min-w-0 @max-[28rem]/query-builder:gap-1.5 @max-[28rem]/query-builder:*:data-[slot=button-group]:flex-1 @max-[28rem]/query-builder:**:data-[slot=query-builder-select-icon]:hidden has-data-[operator=isBetween]:*:data-[slot=button-group]:flex-1 [&>[data-slot=button-group]>*:not(:first-child):focus-visible]:outline-1 [&>[data-slot=button-group]>*:not(:first-child):focus-visible]:outline-solid [&>[data-slot=button-group]>*:not(:first-child):focus-visible]:outline-ring [&>[data-slot=button-group]>*:not(:first-child):focus-visible]:-outline-offset-1 @max-[40rem]/query-builder:data-[operator=isBetween]:items-start @max-[40rem]/query-builder:data-[operator=isBetween]:*:data-[slot=button-group]:flex-wrap @max-[40rem]/query-builder:data-[operator=isBetween]:*:data-[slot=button-group]:gap-y-1 flex items-center", className)}
    />
  );
}

interface CombinatorSelectProps extends React.ComponentProps<
  typeof SelectTrigger
> {
  group: QueryGroup;
  items: Record<QueryCombinator, string>;
}

function CombinatorSelect({
  group,
  items,
  disabled: disabledProp,
  ...props
}: CombinatorSelectProps) {
  const { disabled, labels } = useQueryBuilderContext(COMBINATOR_NAME);
  const isDisabled = disabled || disabledProp;
  const { update } = useQueryActions(COMBINATOR_NAME);

  return (
    <Select
      value={group.combinator}
      onValueChange={(combinator) =>
        update(group.id, (node) => ({
          ...node,
          combinator: combinator as QueryCombinator,
        }))
      }
      disabled={isDisabled}
    >
      <SelectTrigger size="sm" aria-label={labels.combinator} {...props}>
        <SelectValue />
      </SelectTrigger>
      <SelectContent>
        {(["and", "or"] as const).map((combinator) => (
          <SelectItem key={combinator} value={combinator}>
            {items[combinator]}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

function QueryBuilderCombinator({
  className,
  ...props
}: React.ComponentProps<typeof SelectTrigger>) {
  const { labels } = useQueryBuilderContext(COMBINATOR_NAME);
  const { group } = useGroupContext(COMBINATOR_NAME);

  return (
    <CombinatorSelect
      group={group}
      items={{ and: labels.all, or: labels.any }}
      data-slot="query-builder-combinator"
      {...props}
      className={cn("w-20", className)}
    />
  );
}

function QueryBuilderConnector({
  asChild,
  className,
  children,
  ...props
}: DivProps) {
  const { labels } = useQueryBuilderContext(CONNECTOR_NAME);
  const node = React.useContext(NodeContext);

  if (!node) return null;

  const { index, group } = node;
  const target = group.rules[index];
  const items = { and: labels.and, or: labels.or };

  const ConnectorPrimitive = asChild ? SlotPrimitive.Slot : "div";

  return (
    <ConnectorPrimitive
      data-slot="query-builder-connector"
      data-type={target && getIsQueryGroup(target) ? "group" : "rule"}
      {...props}
      className={cn("h-7 w-18 shrink-0 data-[type=group]:mt-2 @max-[28rem]/query-builder:w-15 @max-[28rem]/query-builder:data-[type=group]:mt-0 flex items-center", className)}
    >
      {asChild && <SlotPrimitive.Slottable>{children}</SlotPrimitive.Slottable>}
      {index === 1 ? (
        <CombinatorSelect
          group={group}
          items={items}
          className="w-full rounded-lg data-[size=sm]:rounded-lg @max-[28rem]/query-builder:gap-1 @max-[28rem]/query-builder:px-1.5 @max-[28rem]/query-builder:[&_svg]:hidden"
        />
      ) : (
        <span className="ps-2 text-sm text-muted-foreground @max-[28rem]/query-builder:ps-1">
          {index === 0 ? labels.where : items[group.combinator]}
        </span>
      )}
    </ConnectorPrimitive>
  );
}

function QueryBuilderNegate({
  onClick,
  children,
  className,
  disabled: disabledProp,
  ...props
}: React.ComponentProps<typeof Button>) {
  const { disabled, labels } = useQueryBuilderContext(NEGATE_NAME);
  const isDisabled = disabled || disabledProp;
  const { group } = useGroupContext(NEGATE_NAME);
  const { update } = useQueryActions(NEGATE_NAME);

  return (
    <Button
      type="button"
      variant="ghost"
      size="sm"
      aria-pressed={!!group.not}
      data-slot="query-builder-negate"
      data-state={group.not ? "on" : "off"}
      disabled={isDisabled}
      {...props}
      onClick={(event) => {
        onClick?.(event);
        if (event.defaultPrevented) return;
        update(group.id, (node) =>
          getIsQueryGroup(node) ? { ...node, not: !node.not } : node,
        );
      }}
      className={cn("text-muted-foreground aria-pressed:bg-muted aria-pressed:text-foreground", className)}
    >
      {children ?? labels.not}
    </Button>
  );
}

function QueryBuilderField({
  id,
  "aria-labelledby": ariaLabelledBy,
  className,
  disabled: disabledProp,
  ...props
}: React.ComponentProps<typeof Button>) {
  const { fields, labels, disabled } = useQueryBuilderContext(FIELD_NAME);
  const isDisabled = disabled || disabledProp;
  const generatedId = React.useId();
  const triggerId = id ?? generatedId;
  const rule = useRuleContext(FIELD_NAME);
  const { update } = useQueryActions(FIELD_NAME);
  const currentField = fields.find((field) => field.value === rule.field);

  return (
    <Faceted
      items={fields}
      value={rule.field}
      onValueChange={(value) => {
        const field = fields.find((item) => item.value === value);
        if (!field) return;
        update(rule.id, (node) =>
          setQueryRuleField(node as QueryRule, currentField, field),
        );
      }}
    >
      <FacetedTrigger asChild>
        <Button
          variant="outline"
          size="sm"
          aria-label={
            ariaLabelledBy
              ? currentField
                ? currentField.label
                : labels.field
              : currentField
                ? `${labels.field}: ${currentField.label}`
                : labels.field
          }
          aria-labelledby={
            ariaLabelledBy ? `${ariaLabelledBy} ${triggerId}` : undefined
          }
          title={currentField?.label}
          id={triggerId}
          data-slot="query-builder-field"
          disabled={isDisabled}
          {...props}
          className={cn(
            "w-24 min-w-0 @max-[28rem]/query-builder:w-auto @max-[28rem]/query-builder:not-in-data-[operator=isBetween]:flex-1 @max-[40rem]/query-builder:in-data-[operator=isBetween]:basis-1/2 justify-between gap-1 font-normal transition-[color,background-color,border-color,box-shadow] has-data-[slot=query-builder-value-list]:pl-1",
            className,
          )}
        >
          <FacetedValue>
            {([item]) => (
              <bdi
                className={cn(
                  "min-w-0 truncate",
                  !item && "text-muted-foreground",
                )}
              >
                {item ? item.label : labels.field}
              </bdi>
            )}
          </FacetedValue>
          <ChevronDownIcon data-slot="query-builder-select-icon" className="size-4 shrink-0 opacity-50" />
        </Button>
      </FacetedTrigger>
      <FacetedContent align="start">
        <FacetedInput placeholder={labels.searchFields} />
        <FacetedList>
          <FacetedEmpty>{labels.noFields}</FacetedEmpty>
          <FacetedGroup>
            {fields.map((field) => (
              <FacetedItem key={field.value} value={field.value}>
                <bdi className="flex-1 truncate">{field.label}</bdi>
                <FacetedItemIndicator />
              </FacetedItem>
            ))}
          </FacetedGroup>
        </FacetedList>
      </FacetedContent>
    </Faceted>
  );
}

function QueryBuilderOperator({
  id,
  "aria-labelledby": ariaLabelledBy,
  className,
  disabled: disabledProp,
  ...props
}: React.ComponentProps<typeof Button>) {
  const { fields, labels, disabled } = useQueryBuilderContext(OPERATOR_NAME);
  const isDisabled = disabled || disabledProp;
  const generatedId = React.useId();
  const triggerId = id ?? generatedId;
  const rule = useRuleContext(OPERATOR_NAME);
  const { update } = useQueryActions(OPERATOR_NAME);
  const field = fields.find((item) => item.value === rule.field);

  if (!field) return null;

  const operators = getQueryOperators(field).map((operator) => ({
    label: labels.operatorLabel(operator, field.type),
    value: operator,
  }));

  return (
    <Faceted
      items={operators}
      value={rule.operator}
      onValueChange={(next) => {
        if (!next) return;
        update(rule.id, (node) =>
          setQueryRuleOperator(node as QueryRule, field, next as QueryOperator),
        );
      }}
    >
      <FacetedTrigger asChild>
        <Button
          variant="outline"
          size="sm"
          aria-label={
            ariaLabelledBy
              ? labels.operatorLabel(rule.operator, field.type)
              : `${labels.operator}: ${labels.operatorLabel(rule.operator, field.type)}`
          }
          aria-labelledby={
            ariaLabelledBy ? `${ariaLabelledBy} ${triggerId}` : undefined
          }
          title={labels.operatorLabel(rule.operator, field.type)}
          id={triggerId}
          data-slot="query-builder-operator"
          disabled={isDisabled}
          {...props}
          className={cn(
            "w-28 min-w-0 @max-[28rem]/query-builder:w-auto @max-[28rem]/query-builder:not-in-data-[operator=isBetween]:flex-1 @max-[40rem]/query-builder:in-data-[operator=isBetween]:basis-1/2 @max-[40rem]/query-builder:in-data-[operator=isBetween]:rounded-r-lg! justify-between gap-1 font-normal transition-[color,background-color,border-color,box-shadow] has-data-[slot=query-builder-value-list]:pl-1",
            className,
          )}
        >
          <FacetedValue>
            {([item]) => (
              <bdi className="min-w-0 truncate">{item?.label}</bdi>
            )}
          </FacetedValue>
          <ChevronDownIcon data-slot="query-builder-select-icon" className="size-4 shrink-0 opacity-50" />
        </Button>
      </FacetedTrigger>
      <FacetedContent align="start">
        <FacetedInput placeholder={labels.searchOperators} />
        <FacetedList>
          <FacetedEmpty>{labels.noOperators}</FacetedEmpty>
          <FacetedGroup>
            {operators.map((operator) => (
              <FacetedItem key={operator.value} value={operator.value}>
                <bdi className="flex-1 truncate">{operator.label}</bdi>
                <FacetedItemIndicator />
              </FacetedItem>
            ))}
          </FacetedGroup>
        </FacetedList>
      </FacetedContent>
    </Faceted>
  );
}

function getSelectedValues(value: QueryValue | undefined) {
  if (Array.isArray(value)) return value;
  return value ? [value] : [];
}

function QueryBuilderValueList({ options }: { options: QueryFieldOption[] }) {
  const listRef = React.useRef<HTMLSpanElement>(null);
  const itemRefs = React.useRef<(HTMLSpanElement | null)[]>([]);
  const labelRefs = React.useRef<(HTMLElement | null)[]>([]);
  const countRef = React.useRef<HTMLSpanElement>(null);
  const [visibleCount, setVisibleCount] = React.useState(options.length);

  React.useLayoutEffect(() => {
    const list = listRef.current;
    if (!list) return;

    function measure() {
      if (!list) return;
      const widths = options.map((_, index) => {
        const item = itemRefs.current[index];
        const label = labelRefs.current[index];
        if (!item) return 0;
        if (!label) return item.getBoundingClientRect().width;
        return (
          item.getBoundingClientRect().width -
          label.getBoundingClientRect().width +
          label.scrollWidth
        );
      });
      const gap = Number.parseFloat(getComputedStyle(list).columnGap) || 0;
      const available = list.getBoundingClientRect().width;
      const total = widths.reduce((sum, width) => sum + width + gap, -gap);
      if (total <= available) {
        setVisibleCount(widths.length);
        return;
      }
      let used = countRef.current?.getBoundingClientRect().width ?? 24;
      let count = 0;
      for (const width of widths) {
        if (used + gap + width > available) break;
        used += gap + width;
        count++;
      }
      setVisibleCount(Math.max(1, count));
    }

    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(list);
    return () => observer.disconnect();
  });

  const hiddenCount = Math.max(0, options.length - visibleCount);

  return (
    <span
      ref={listRef}
      data-slot="query-builder-value-list"
      className="relative flex min-w-0 flex-1 items-center gap-1 overflow-hidden"
    >
      {options.map(({ label, value }, index) => (
        <span
          key={value}
          ref={(node) => {
            itemRefs.current[index] = node;
          }}
          data-slot="query-builder-value-item"
          data-hidden={index >= visibleCount ? "" : undefined}
          className="flex min-w-0 shrink-0 items-center first:shrink data-hidden:invisible data-hidden:absolute"
        >
          <FacetedBadge>
            <bdi
              ref={(node) => {
                labelRefs.current[index] = node;
              }}
              className="truncate"
            >
              {label}
            </bdi>
          </FacetedBadge>
        </span>
      ))}
      {hiddenCount > 0 && (
        <FacetedBadge ref={countRef} className="shrink-0">
          +{hiddenCount}
        </FacetedBadge>
      )}
    </span>
  );
}

interface QueryBuilderValueProps extends Omit<
  React.HTMLAttributes<HTMLElement>,
  "children" | "defaultValue" | "onChange"
> {
  display?: "list" | "summary";
  disabled?: boolean;
}

function QueryBuilderValue({
  display = "list",
  id,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  className,
  disabled: disabledProp,
  ...props
}: QueryBuilderValueProps) {
  const { fields, labels, disabled } = useQueryBuilderContext(VALUE_NAME);
  const isDisabled = disabled || disabledProp;
  const rule = useRuleContext(VALUE_NAME);
  const { update } = useQueryActions(VALUE_NAME);
  const field = fields.find((item) => item.value === rule.field);

  const generatedId = React.useId();

  if (!field) return null;

  const label = ariaLabel ?? field.label;

  const onChange = (value: QueryValue) =>
    update(rule.id, (node) => ({ ...node, value }));

  const inputType =
    field.type === "number"
      ? "number"
      : field.type === "date"
        ? "date"
        : "text";

  const valueClassName = cn("cn-query-builder-value", className);

  if (rule.operator === "isEmpty" || rule.operator === "isNotEmpty") {
    return (
      <Input
        aria-hidden="true"
        tabIndex={-1}
        id={id}
        {...props}
        value=""
        readOnly
        data-slot="query-builder-value"
        data-operator={rule.operator}
        className={cn("pointer-events-none", valueClassName)}
      />
    );
  }

  if (rule.operator === "isBetween") {
    const [start = "", end = ""] = Array.isArray(rule.value) ? rule.value : [];
    const fromId = id ?? `${generatedId}-from`;
    const toId = `${generatedId}-to`;
    return (
      <>
        <Input
          type={inputType}
          id={fromId}
          placeholder={labels.from}
          aria-label={ariaLabelledBy ? labels.from : `${label} ${labels.from}`}
          aria-labelledby={
            ariaLabelledBy ? `${ariaLabelledBy} ${fromId}` : undefined
          }
          {...props}
          data-slot="query-builder-value"
          data-operator={rule.operator}
          value={start}
          onChange={(event) => onChange([event.target.value, end])}
          disabled={isDisabled}
          className={valueClassName}
        />
        <span className="flex h-7 items-center border-y border-e border-input bg-transparent dark:bg-input/30 px-1.5 text-sm text-muted-foreground @max-[40rem]/query-builder:hidden">
          {labels.between}
        </span>
        <Input
          type={inputType}
          id={toId}
          placeholder={labels.to}
          aria-label={ariaLabelledBy ? labels.to : `${label} ${labels.to}`}
          aria-labelledby={
            ariaLabelledBy ? `${ariaLabelledBy} ${toId}` : undefined
          }
          {...props}
          data-slot="query-builder-value"
          data-operator={rule.operator}
          value={end}
          onChange={(event) => onChange([start, event.target.value])}
          disabled={isDisabled}
          className={valueClassName}
        />
      </>
    );
  }

  if (
    field.type === "boolean" ||
    field.type === "select" ||
    field.type === "multiSelect"
  ) {
    const options =
      field.type === "boolean"
        ? [
            { label: labels.true, value: "true" },
            { label: labels.false, value: "false" },
          ]
        : (field.options ?? []);
    const multiple = getIsQueryRuleMultiple(rule, field);
    const selected = getSelectedValues(rule.value).flatMap((value) =>
      options.filter((option) => option.value === value),
    );
    const selectedLabels = selected.map((option) => option.label).join(", ");

    return (
      <Faceted
        items={options}
        multiple={multiple}
        value={multiple ? getSelectedValues(rule.value) : rule.value}
        onValueChange={(next) =>
          update(rule.id, (node) =>
            setQueryRuleValues(
              node as QueryRule,
              field,
              getSelectedValues(next),
            ),
          )
        }
      >
        <FacetedTrigger asChild>
          <Button
            variant="outline"
            size="sm"
            aria-label={
              ariaLabelledBy
                ? selectedLabels || labels.noValue
                : `${label}: ${selectedLabels || labels.noValue}`
            }
            aria-labelledby={
              ariaLabelledBy
                ? `${ariaLabelledBy} ${id ?? generatedId}`
                : undefined
            }
            title={selectedLabels || undefined}
            id={id ?? generatedId}
            {...props}
            data-slot="query-builder-value"
            data-operator={rule.operator}
            disabled={isDisabled}
            className={cn("justify-between gap-1 font-normal transition-[color,background-color,border-color,box-shadow] has-data-[slot=query-builder-value-list]:pl-1", valueClassName)}
          >
            <FacetedValue>
              {() => {
                if (selected.length > 0 && display === "summary") {
                  return (
                    <bdi className="min-w-0 truncate">
                      {selected.length > 1
                        ? labels.selected(selected.length)
                        : selected[0]?.label}
                    </bdi>
                  );
                }
                if (selected.length > 0) {
                  return <QueryBuilderValueList options={selected} />;
                }
                return (
                  <bdi className="min-w-0 truncate text-muted-foreground">
                    {field.placeholder ??
                      (multiple ? labels.selectValues : labels.selectValue)}
                  </bdi>
                );
              }}
            </FacetedValue>
            <ChevronDownIcon data-slot="query-builder-select-icon" className="size-4 shrink-0 opacity-50" />
          </Button>
        </FacetedTrigger>
        <FacetedContent align="start">
          <FacetedInput placeholder={labels.searchValues(field.label)} />
          <FacetedList>
            <FacetedEmpty>{labels.noValues}</FacetedEmpty>
            <FacetedGroup>
              {options.map((option) => (
                <FacetedItem key={option.value} value={option.value}>
                  {option.icon && <option.icon aria-hidden="true" />}
                  <bdi className="flex-1 truncate">{option.label}</bdi>
                  <FacetedItemIndicator />
                </FacetedItem>
              ))}
            </FacetedGroup>
            {multiple && <FacetedClear />}
          </FacetedList>
        </FacetedContent>
      </Faceted>
    );
  }

  return (
    <Input
      type={inputType}
      aria-label={label}
      aria-labelledby={ariaLabelledBy}
      placeholder={field.placeholder ?? labels.enterValue}
      id={id}
      {...props}
      value={typeof rule.value === "string" ? rule.value : ""}
      onChange={(event) => onChange(event.target.value)}
      disabled={isDisabled}
      data-slot="query-builder-value"
      data-operator={rule.operator}
      className={valueClassName}
    />
  );
}

function getField(fields: QueryField[], value?: string) {
  return value === undefined
    ? fields[0]
    : fields.find((field) => field.value === value);
}

interface QueryBuilderAddRuleProps extends React.ComponentProps<typeof Button> {
  field?: string;
}

function QueryBuilderAddRule({
  field: fieldProp,
  onClick,
  children,
  className,
  disabled: disabledProp,
  ...props
}: QueryBuilderAddRuleProps) {
  const { fields, labels, disabled } = useQueryBuilderContext(ADD_RULE_NAME);
  const isDisabled = disabled || disabledProp;
  const { group } = useGroupContext(ADD_RULE_NAME);
  const { add } = useQueryActions(ADD_RULE_NAME);
  const field = getField(fields, fieldProp);

  return (
    <Button
      type="button"
      variant="ghost"
      size="sm"
      data-slot="query-builder-add-rule"
      disabled={isDisabled || !field}
      {...props}
      onClick={(event) => {
        onClick?.(event);
        if (event.defaultPrevented || !field) return;
        add(group.id, createQueryRule(field));
      }}
      className={cn("text-muted-foreground", className)}
    >
      {children ?? (
        <>
          <PlusIcon />
          {labels.addRule}
        </>
      )}
    </Button>
  );
}

interface QueryBuilderAddGroupProps extends React.ComponentProps<
  typeof Button
> {
  field?: string;
}

function QueryBuilderAddGroup({
  field: fieldProp,
  onClick,
  children,
  className,
  disabled: disabledProp,
  ...props
}: QueryBuilderAddGroupProps) {
  const { fields, labels, disabled, maxDepth } =
    useQueryBuilderContext(ADD_GROUP_NAME);
  const isDisabled = disabled || disabledProp;
  const { group, depth } = useGroupContext(ADD_GROUP_NAME);
  const { add } = useQueryActions(ADD_GROUP_NAME);
  const field = getField(fields, fieldProp);

  if (depth >= maxDepth) return null;

  return (
    <Button
      type="button"
      variant="ghost"
      size="sm"
      data-slot="query-builder-add-group"
      disabled={isDisabled || !field}
      {...props}
      onClick={(event) => {
        onClick?.(event);
        if (event.defaultPrevented || !field) return;
        add(
          group.id,
          createQueryGroup(group.combinator === "and" ? "or" : "and", [
            createQueryRule(field),
          ]),
        );
      }}
      className={cn("text-muted-foreground", className)}
    >
      {children ?? (
        <>
          <ListPlusIcon />
          {labels.addGroup}
        </>
      )}
    </Button>
  );
}

function QueryBuilderRemove({
  onClick,
  children,
  className,
  disabled: disabledProp,
  ...props
}: React.ComponentProps<typeof Button>) {
  const { disabled, labels } = useQueryBuilderContext(REMOVE_NAME);
  const isDisabled = disabled || disabledProp;
  const rule = React.useContext(RuleContext);
  const group = useGroupContext(REMOVE_NAME);
  const { remove } = useQueryActions(REMOVE_NAME);

  const id = rule?.id ?? (group.isRoot ? undefined : group.group.id);
  if (!id) return null;

  return (
    <Button
      type="button"
      variant="ghost"
      size="icon-sm"
      aria-label={rule ? labels.removeRule : labels.removeGroup}
      data-slot="query-builder-remove"
      disabled={isDisabled}
      {...props}
      onClick={(event) => {
        onClick?.(event);
        if (event.defaultPrevented) return;
        remove(id);
      }}
      className={cn("text-muted-foreground", className)}
    >
      {children ?? (
        <Trash2Icon />
      )}
    </Button>
  );
}

export {
  QueryBuilder,
  QueryBuilderAddGroup,
  QueryBuilderAddRule,
  QueryBuilderCombinator,
  QueryBuilderConnector,
  QueryBuilderField,
  QueryBuilderGroup,
  QueryBuilderGroupContent,
  QueryBuilderGroupFooter,
  QueryBuilderGroupHeader,
  QueryBuilderGroupTitle,
  QueryBuilderNegate,
  QueryBuilderOperator,
  QueryBuilderRemove,
  QueryBuilderRule,
  QueryBuilderRuleList,
  QueryBuilderValue,
};

import type * as React from "react";

export type QueryFieldType =
  | "text"
  | "number"
  | "date"
  | "boolean"
  | "select"
  | "multiSelect";

export type QueryOperator =
  | "iLike"
  | "notILike"
  | "eq"
  | "ne"
  | "lt"
  | "lte"
  | "gt"
  | "gte"
  | "isBetween"
  | "inArray"
  | "notInArray"
  | "isEmpty"
  | "isNotEmpty";

export type QueryCombinator = "and" | "or";

export type QueryValue = string | string[];

export interface QueryFieldOption {
  label: string;
  value: string;
  icon?: React.ComponentType<React.ComponentProps<"svg">>;
}

export interface QueryField {
  value: string;
  label: string;
  type: QueryFieldType;
  column?: string;
  operators?: QueryOperator[];
  options?: QueryFieldOption[];
  placeholder?: string;
}

export interface QueryRule {
  id: string;
  field: string;
  operator: QueryOperator;
  value?: QueryValue;
}

export interface QueryGroup {
  id: string;
  combinator: QueryCombinator;
  not?: boolean;
  rules: QueryNode[];
}

export type QueryNode = QueryRule | QueryGroup;

export type QuerySelection = Record<string, string[]>;

export const QUERY_OPERATORS: Record<QueryFieldType, QueryOperator[]> = {
  text: ["iLike", "notILike", "eq", "ne", "isEmpty", "isNotEmpty"],
  number: [
    "eq",
    "ne",
    "lt",
    "lte",
    "gt",
    "gte",
    "isBetween",
    "isEmpty",
    "isNotEmpty",
  ],
  date: [
    "eq",
    "ne",
    "lt",
    "gt",
    "lte",
    "gte",
    "isBetween",
    "isEmpty",
    "isNotEmpty",
  ],
  boolean: ["eq", "ne"],
  select: ["eq", "ne", "inArray", "notInArray", "isEmpty", "isNotEmpty"],
  multiSelect: ["inArray", "notInArray", "isEmpty", "isNotEmpty"],
};

const OPERATOR_LABELS: Record<QueryOperator, string> = {
  iLike: "contains",
  notILike: "does not contain",
  eq: "is",
  ne: "is not",
  lt: "is less than",
  lte: "is at most",
  gt: "is greater than",
  gte: "is at least",
  isBetween: "is between",
  inArray: "is any of",
  notInArray: "is none of",
  isEmpty: "is empty",
  isNotEmpty: "is not empty",
};

const DATE_OPERATOR_LABELS: Partial<Record<QueryOperator, string>> = {
  lt: "is before",
  lte: "is on or before",
  gt: "is after",
  gte: "is on or after",
};

export function getQueryOperators(field: QueryField): QueryOperator[] {
  return field.operators ?? QUERY_OPERATORS[field.type];
}

export function getQueryOperatorLabel(
  operator: QueryOperator,
  type?: QueryFieldType,
): string {
  return (
    (type === "date" ? DATE_OPERATOR_LABELS[operator] : undefined) ??
    OPERATOR_LABELS[operator]
  );
}

export function getIsQueryGroup(node: QueryNode): node is QueryGroup {
  return "rules" in node;
}

function createId() {
  return typeof crypto !== "undefined" && "randomUUID" in crypto
    ? crypto.randomUUID()
    : Math.random().toString(36).slice(2);
}

export function createQueryRule(field: QueryField): QueryRule {
  const operator = getQueryOperators(field)[0] ?? "eq";
  return {
    id: createId(),
    field: field.value,
    operator,
    value: getDefaultQueryValue(field, operator),
  };
}

export function createQueryGroup(
  combinator: QueryCombinator = "and",
  rules: QueryNode[] = [],
): QueryGroup {
  return { id: createId(), combinator, rules };
}

export function getDefaultQueryValue(
  field: QueryField,
  operator: QueryOperator,
): QueryValue | undefined {
  if (operator === "isEmpty" || operator === "isNotEmpty") return undefined;
  if (operator === "isBetween") return ["", ""];
  if (operator === "inArray" || operator === "notInArray") return [];
  if (field.type === "boolean") return "true";
  return "";
}

function getIsListOperator(operator: QueryOperator) {
  return operator === "inArray" || operator === "notInArray";
}

function getQueryValueForOperator(
  rule: QueryRule,
  operator: QueryOperator,
): QueryValue | undefined {
  const { value } = rule;
  if (operator === "isEmpty" || operator === "isNotEmpty") return undefined;
  if ((rule.operator === "isBetween") !== (operator === "isBetween")) {
    return undefined;
  }
  if (getIsListOperator(operator)) {
    if (Array.isArray(value)) return value;
    return value ? [value] : undefined;
  }
  if (Array.isArray(value) && operator !== "isBetween") return value[0];
  return value;
}

export function setQueryRuleOperator(
  rule: QueryRule,
  field: QueryField,
  operator: QueryOperator,
): QueryRule {
  return {
    ...rule,
    operator,
    value:
      getQueryValueForOperator(rule, operator) ??
      getDefaultQueryValue(field, operator),
  };
}

export function setQueryRuleField(
  rule: QueryRule,
  from: QueryField | undefined,
  to: QueryField,
): QueryRule {
  if (
    !from ||
    from.type !== to.type ||
    !getQueryOperators(to).includes(rule.operator)
  ) {
    return { ...createQueryRule(to), id: rule.id };
  }
  if (to.type !== "select" && to.type !== "multiSelect") {
    return { ...rule, field: to.value };
  }
  const options = new Set(to.options?.map((option) => option.value));
  if (Array.isArray(rule.value)) {
    return setQueryRuleValues(
      { ...rule, field: to.value },
      to,
      rule.value.filter((item) => options.has(item)),
    );
  }
  const value =
    rule.value && options.has(rule.value)
      ? rule.value
      : getDefaultQueryValue(to, rule.operator);
  return { ...rule, field: to.value, value };
}

const OPERATOR_COUNTERPARTS: Partial<Record<QueryOperator, QueryOperator>> = {
  eq: "inArray",
  ne: "notInArray",
  inArray: "eq",
  notInArray: "ne",
};

function getOperatorCounterpart(operator: QueryOperator, field: QueryField) {
  const counterpart = OPERATOR_COUNTERPARTS[operator];
  return counterpart && getQueryOperators(field).includes(counterpart)
    ? counterpart
    : undefined;
}

export function getIsQueryRuleMultiple(rule: QueryRule, field: QueryField) {
  return (
    getIsListOperator(rule.operator) ||
    getOperatorCounterpart(rule.operator, field) !== undefined
  );
}

export function setQueryRuleValues(
  rule: QueryRule,
  field: QueryField,
  values: string[],
): QueryRule {
  const counterpart = getOperatorCounterpart(rule.operator, field);
  const operator =
    counterpart &&
    values.length > 0 &&
    values.length > 1 !== getIsListOperator(rule.operator)
      ? counterpart
      : rule.operator;
  return {
    ...rule,
    operator,
    value: getIsListOperator(operator) ? values : (values[0] ?? ""),
  };
}

function getRuleValues(rule: QueryRule) {
  if (Array.isArray(rule.value)) return rule.value;
  return rule.value ? [rule.value] : [];
}

function getIsSameValues(a: string[], b: string[]) {
  return a.length === b.length && a.every((value, index) => value === b[index]);
}

export function getQuerySelection(query: QueryGroup): QuerySelection {
  const selection: QuerySelection = {};
  for (const node of query.rules) {
    if (getIsQueryGroup(node) || selection[node.field]) continue;
    selection[node.field] = getRuleValues(node);
  }
  return selection;
}

export function setQuerySelection(
  query: QueryGroup,
  fields: QueryField[],
  selection: QuerySelection,
): QueryGroup {
  const current = getQuerySelection(query);
  let rules = query.rules;
  for (const field of fields) {
    const values = selection[field.value] ?? [];
    if (getIsSameValues(values, current[field.value] ?? [])) continue;
    const rule = rules.find(
      (node): node is QueryRule =>
        !getIsQueryGroup(node) && node.field === field.value,
    );
    if (values.length === 0) {
      rules = rules.filter((node) => node !== rule);
    } else if (rule) {
      rules = rules.map((node) =>
        node === rule ? setQueryRuleValues(rule, field, values) : node,
      );
    } else {
      rules = [
        ...rules,
        setQueryRuleValues(createQueryRule(field), field, values),
      ];
    }
  }
  return rules === query.rules ? query : { ...query, rules };
}

export function updateQueryNode(
  root: QueryGroup,
  id: string,
  updater: (node: QueryNode) => QueryNode,
): QueryGroup {
  if (root.id === id) {
    const next = updater(root);
    return getIsQueryGroup(next) ? next : root;
  }
  let changed = false;
  const rules = root.rules.map((node) => {
    const next = getIsQueryGroup(node)
      ? updateQueryNode(node, id, updater)
      : node.id === id
        ? updater(node)
        : node;
    if (next !== node) changed = true;
    return next;
  });
  return changed ? { ...root, rules } : root;
}

export function removeQueryNode(root: QueryGroup, id: string): QueryGroup {
  let changed = false;
  const rules: QueryNode[] = [];
  for (const node of root.rules) {
    if (node.id === id) {
      changed = true;
      continue;
    }
    const next = getIsQueryGroup(node) ? removeQueryNode(node, id) : node;
    if (next !== node) changed = true;
    rules.push(next);
  }
  return changed ? { ...root, rules } : root;
}

export function addQueryNode(
  root: QueryGroup,
  groupId: string,
  node: QueryNode,
): QueryGroup {
  return updateQueryNode(root, groupId, (group) =>
    getIsQueryGroup(group)
      ? { ...group, rules: [...group.rules, node] }
      : group,
  );
}

export function findQueryNode(
  root: QueryGroup,
  id: string,
): QueryNode | undefined {
  if (root.id === id) return root;
  for (const node of root.rules) {
    if (node.id === id) return node;
    if (getIsQueryGroup(node)) {
      const found = findQueryNode(node, id);
      if (found) return found;
    }
  }
  return undefined;
}

export function moveQueryNode(
  root: QueryGroup,
  id: string,
  groupId: string,
  index: number,
): QueryGroup {
  const node = findQueryNode(root, id);
  if (!node || node === root) return root;
  if (getIsQueryGroup(node) && findQueryNode(node, groupId)) return root;
  const group = findQueryNode(root, groupId);
  if (!group || !getIsQueryGroup(group)) return root;
  return updateQueryNode(removeQueryNode(root, id), groupId, (group) => {
    if (!getIsQueryGroup(group)) return group;
    const rules = [...group.rules];
    rules.splice(index, 0, node);
    return { ...group, rules };
  });
}

function getField(fields: QueryField[], value: string) {
  return fields.find((field) => field.value === value);
}

function getIsFilled(value: unknown) {
  return typeof value === "string" && value.trim() !== "";
}

export function getIsQueryRuleActive(rule: QueryRule, field?: QueryField) {
  if (!field || !getQueryOperators(field).includes(rule.operator)) {
    return false;
  }
  const { operator, value } = rule;
  if (operator === "isEmpty" || operator === "isNotEmpty") return true;
  if (operator === "isBetween") {
    return (
      Array.isArray(value) && (getIsFilled(value[0]) || getIsFilled(value[1]))
    );
  }
  if (operator === "inArray" || operator === "notInArray") {
    return Array.isArray(value) && value.length > 0;
  }
  if (field.type === "number" && typeof value === "string") {
    return getIsFilled(value) && Number.isFinite(Number(value));
  }
  return getIsFilled(value);
}

function getDateKey(value: unknown): string | undefined {
  if (value instanceof Date) {
    if (Number.isNaN(value.getTime())) return undefined;
    const month = String(value.getMonth() + 1).padStart(2, "0");
    const day = String(value.getDate()).padStart(2, "0");
    return `${value.getFullYear()}-${month}-${day}`;
  }
  if (typeof value === "number") return getDateKey(new Date(value));
  if (typeof value === "string") {
    const match = value.match(/^\d{4}-\d{2}-\d{2}/);
    return match ? match[0] : getDateKey(new Date(value));
  }
  return undefined;
}

function getNextDateKey(key: string) {
  const date = new Date(`${key}T00:00:00Z`);
  date.setUTCDate(date.getUTCDate() + 1);
  return date.toISOString().slice(0, 10);
}

function getCellText(value: unknown): string {
  if (value === null || value === undefined) return "";
  if (value instanceof Date) return value.toISOString();
  if (typeof value === "object") return JSON.stringify(value);
  if (typeof value === "string") return value;
  if (
    typeof value === "number" ||
    typeof value === "boolean" ||
    typeof value === "bigint"
  ) {
    return value.toString();
  }
  return "";
}

function getIsEmptyCell(value: unknown) {
  return (
    value === null ||
    value === undefined ||
    (typeof value === "string" && value.trim() === "") ||
    (Array.isArray(value) && value.length === 0)
  );
}

function compare<T>(left: T, operator: QueryOperator, right: T) {
  switch (operator) {
    case "eq":
      return left === right;
    case "ne":
      return left !== right;
    case "lt":
      return left < right;
    case "lte":
      return left <= right;
    case "gt":
      return left > right;
    case "gte":
      return left >= right;
    default:
      return false;
  }
}

function matchesRule(cell: unknown, rule: QueryRule, field: QueryField) {
  const { operator, value } = rule;

  if (operator === "isEmpty") return getIsEmptyCell(cell);
  if (operator === "isNotEmpty") return !getIsEmptyCell(cell);

  if (operator === "inArray" || operator === "notInArray") {
    const values = Array.isArray(value) ? value : [];
    const cells = Array.isArray(cell)
      ? cell.map(getCellText)
      : [getCellText(cell)];
    const hasAny = cells.some((item) => values.includes(item));
    return operator === "inArray" ? hasAny : !hasAny;
  }

  if (field.type === "number") {
    const number = typeof cell === "number" ? cell : Number(cell);
    if (getIsEmptyCell(cell) || Number.isNaN(number)) return false;
    if (operator === "isBetween" && Array.isArray(value)) {
      const [min, max] = value;
      return (
        (!getIsFilled(min) || number >= Number(min)) &&
        (!getIsFilled(max) || number <= Number(max))
      );
    }
    return compare(number, operator, Number(value));
  }

  if (field.type === "date") {
    const key = getDateKey(cell);
    if (!key) return false;
    if (operator === "isBetween" && Array.isArray(value)) {
      const [start, end] = value;
      return (
        (!getIsFilled(start) || key >= (start as string)) &&
        (!getIsFilled(end) || key <= (end as string))
      );
    }
    return compare(key, operator, String(value));
  }

  const text = getCellText(cell);
  if (operator === "iLike" || operator === "notILike") {
    const contains = text.toLowerCase().includes(String(value).toLowerCase());
    return operator === "iLike" ? contains : !contains;
  }
  return compare(text, operator, String(value));
}

function matchesGroup(
  row: Record<string, unknown>,
  group: QueryGroup,
  fields: QueryField[],
): boolean | undefined {
  const results: boolean[] = [];
  for (const node of group.rules) {
    if (getIsQueryGroup(node)) {
      const result = matchesGroup(row, node, fields);
      if (result !== undefined) results.push(result);
      continue;
    }
    const field = getField(fields, node.field);
    if (!field || !getIsQueryRuleActive(node, field)) continue;
    results.push(matchesRule(row[field.value], node, field));
  }
  if (results.length === 0) return undefined;
  const matches =
    group.combinator === "and" ? results.every(Boolean) : results.some(Boolean);
  return group.not ? !matches : matches;
}

export function matchesQuery(
  row: Record<string, unknown>,
  query: QueryGroup,
  fields: QueryField[],
): boolean {
  return matchesGroup(row, query, fields) ?? true;
}

export type SqlDialect = "postgres" | "mysql" | "sqlite";

export interface FormatQueryOptions {
  dialect?: SqlDialect;
}

export interface FormattedQuery {
  sql: string;
  params: unknown[];
}

function quoteIdentifier(identifier: string, dialect: SqlDialect) {
  const quote = dialect === "mysql" ? "`" : '"';
  return identifier
    .split(".")
    .map((part) => `${quote}${part.replaceAll(quote, quote + quote)}${quote}`)
    .join(".");
}

function escapeLike(value: string) {
  return value.replace(/[!%_]/g, "!$&");
}

function formatRule(
  rule: QueryRule,
  field: QueryField,
  dialect: SqlDialect,
  addParam: (value: unknown) => string,
): string | undefined {
  const column = quoteIdentifier(field.column ?? field.value, dialect);
  const { operator, value } = rule;

  if (operator === "isEmpty" || operator === "isNotEmpty") {
    const isText = field.type === "text" || field.type === "select";
    if (operator === "isEmpty") {
      return isText
        ? `(${column} IS NULL OR ${column} = '')`
        : `${column} IS NULL`;
    }
    return isText
      ? `(${column} IS NOT NULL AND ${column} <> '')`
      : `${column} IS NOT NULL`;
  }

  if (operator === "inArray" || operator === "notInArray") {
    const values = Array.isArray(value) ? value : [];
    const list = values.map((item) => addParam(item)).join(", ");
    return `${column} ${operator === "inArray" ? "IN" : "NOT IN"} (${list})`;
  }

  if (operator === "iLike" || operator === "notILike") {
    const pattern = addParam(`%${escapeLike(String(value))}%`);
    const negate = operator === "notILike" ? "NOT " : "";
    return dialect === "postgres"
      ? `${column} ${negate}ILIKE ${pattern} ESCAPE '!'`
      : `LOWER(${column}) ${negate}LIKE LOWER(${pattern}) ESCAPE '!'`;
  }

  if (field.type === "date") {
    if (operator === "isBetween" && Array.isArray(value)) {
      const [start, end] = value;
      const parts = [
        getIsFilled(start) ? `${column} >= ${addParam(start)}` : undefined,
        getIsFilled(end)
          ? `${column} < ${addParam(getNextDateKey(end as string))}`
          : undefined,
      ].filter(Boolean);
      return parts.length > 1 ? `(${parts.join(" AND ")})` : parts[0];
    }
    const day = String(value);
    const nextDay = getNextDateKey(day);
    switch (operator) {
      case "eq":
        return `(${column} >= ${addParam(day)} AND ${column} < ${addParam(nextDay)})`;
      case "ne":
        return `(${column} < ${addParam(day)} OR ${column} >= ${addParam(nextDay)})`;
      case "lt":
        return `${column} < ${addParam(day)}`;
      case "lte":
        return `${column} < ${addParam(nextDay)}`;
      case "gt":
        return `${column} >= ${addParam(nextDay)}`;
      case "gte":
        return `${column} >= ${addParam(day)}`;
      default:
        return undefined;
    }
  }

  const toParam = (input: unknown) => {
    if (field.type === "number") return Number(input);
    if (field.type === "boolean") return input === "true";
    return input;
  };

  if (operator === "isBetween" && Array.isArray(value)) {
    const [min, max] = value;
    const parts = [
      getIsFilled(min) ? `${column} >= ${addParam(toParam(min))}` : undefined,
      getIsFilled(max) ? `${column} <= ${addParam(toParam(max))}` : undefined,
    ].filter(Boolean);
    return parts.length > 1 ? `(${parts.join(" AND ")})` : parts[0];
  }

  const symbols: Partial<Record<QueryOperator, string>> = {
    eq: "=",
    ne: "<>",
    lt: "<",
    lte: "<=",
    gt: ">",
    gte: ">=",
  };
  const symbol = symbols[operator];
  return symbol ? `${column} ${symbol} ${addParam(toParam(value))}` : undefined;
}

function formatGroup(
  group: QueryGroup,
  fields: QueryField[],
  dialect: SqlDialect,
  addParam: (value: unknown) => string,
): string | undefined {
  const parts: string[] = [];
  for (const node of group.rules) {
    if (getIsQueryGroup(node)) {
      const part = formatGroup(node, fields, dialect, addParam);
      if (part) parts.push(`(${part})`);
      continue;
    }
    const field = getField(fields, node.field);
    if (!field || !getIsQueryRuleActive(node, field)) continue;
    const part = formatRule(node, field, dialect, addParam);
    if (part) parts.push(part);
  }
  if (parts.length === 0) return undefined;
  const sql = parts.join(group.combinator === "and" ? " AND " : " OR ");
  return group.not ? `NOT (${sql})` : sql;
}

export function formatQuery(
  query: QueryGroup,
  fields: QueryField[],
  options: FormatQueryOptions = {},
): FormattedQuery {
  const { dialect = "postgres" } = options;
  const params: unknown[] = [];
  const addParam = (value: unknown) => {
    params.push(value);
    return dialect === "postgres" ? `$${params.length}` : "?";
  };
  const sql = formatGroup(query, fields, dialect, addParam) ?? "";
  return { sql, params };
}

